    int idx = 0;

    // Kahn’s algorithm
    while (front < rear) {
        int node = queue[front++];
        order[idx++] = node;

        // Decrease indegree of neighbors
        for (int i = 0; i < adjCount[node]; i++) {
            int next = adj[node][i];
            indegree[next]--;
            if (indegree[next] == 0) {
