Here’s the operational strategy: for a tree, the minimum-height roots always sit at the **center**. The most efficient way to discover those centers is to iteratively prune leaf nodes—like peeling an onion—until the core stabilizes. This approach is linear, scalable, and aligned with production-grade expectations for large n.

Below is a clean C implementation aligned with your function signature. It uses the standard leaf-trimming BFS workflow.

```c
#include <stdlib.h>

int* findMinHeightTrees(int n, int** edges, int edgesSize, int* edgesColSize, int* returnSize) {
    // Edge case: single node
    if (n == 1) {
        int* res = (int*)malloc(sizeof(int));
        res[0] = 0;
        *returnSize = 1;
        return res;
    }

    // Degree array
    int* degree = (int*)calloc(n, sizeof(int));

    // Adjacency list
    int** adj = (int**)malloc(n * sizeof(int*));
    int* adjCount = (int*)calloc(n, sizeof(int));

    // First pass to count adjacency sizes
    for (int i = 0; i < edgesSize; i++) {
        int a = edges[i][0];
        int b = edges[i][1];
        adjCount[a]++;
        adjCount[b]++;
        degree[a]++;
        degree[b]++;
    }

    // Allocate adjacency buckets
    for (int i = 0; i < n; i++) {
        adj[i] = (int*)malloc(adjCount[i] * sizeof(int));
        adjCount[i] = 0;
    }

    // Fill adjacency lists
    for (int i = 0; i < edgesSize; i++) {
        int a = edges[i][0];
        int b = edges[i][1];
        adj[a][adjCount[a]++] = b;
        adj[b][adjCount[b]++] = a;
    }

    // Initial leaf queue
    int* queue = (int*)malloc(n * sizeof(int));
    int front = 0, rear = 0;

    for (int i = 0; i < n; i++) {
        if (degree[i] == 1) {
            queue[rear++] = i;
        }
    }

    int remaining = n;
    int* result = (int*)malloc(n * sizeof(int));
    int resultCount = 0;

    // Peel off leaves layer by layer
    while (remaining > 2) {
        int leafCount = rear - front;
        remaining -= leafCount;

        for (int i = 0; i < leafCount; i++) {
            int leaf = queue[front++];

            for (int j = 0; j < adjCount[leaf]; j++) {
                int neighbor = adj[leaf][j];
                degree[neighbor]--;

                if (degree[neighbor] == 1) {
                    queue[rear++] = neighbor;
                }
            }
        }
    }

    // Whatever remains in the queue are the tree centers
    resultCount = rear - front;
    for (int i = 0; i < resultCount; i++) {
        result[i] = queue[front + i];
    }

    *returnSize = resultCount;

    for (int i = 0; i < n; i++) {
        free(adj[i]);
    }
    free(adj);
    free(adjCount);
    free(degree);
    free(queue);

    return result;
}
```

