```c
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// Simple string hash function for mapping variable names to indices
unsigned long hashStr(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;
    return hash;
}

typedef struct Entry {
    char key[16];
    int value;
    struct Entry* next;
} Entry;

typedef struct {
    Entry** buckets;
    int size;
} HashMap;

HashMap* createMap(int size) {
    HashMap* map = (HashMap*)malloc(sizeof(HashMap));
    map->buckets = (Entry**)calloc(size, sizeof(Entry*));
    map->size = size;
    return map;
}

int mapGet(HashMap* map, const char* key) {
    unsigned long hash = hashStr(key) % map->size;
    Entry* e = map->buckets[hash];
    while (e) {
        if (strcmp(e->key, key) == 0)
            return e->value;
        e = e->next;
    }
    return -1;
}

void mapPut(HashMap* map, const char* key, int value) {
    unsigned long hash = hashStr(key) % map->size;
    Entry* e = (Entry*)malloc(sizeof(Entry));
    strcpy(e->key, key);
    e->value = value;
    e->next = map->buckets[hash];
    map->buckets[hash] = e;
}

double bfs(int start, int end, int n, int* adjCount, int** adj, double** weight) {
    if (start == end) return 1.0;

    double* dist = (double*)malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) dist[i] = -1.0;

    double* queueVal = (double*)malloc(n * sizeof(double));
    int* queue = (int*)malloc(n * sizeof(int));
    int front = 0, rear = 0;

    queue[rear] = start;
    queueVal[rear] = 1.0;
    rear++;
    dist[start] = 1.0;

    while (front < rear) {
        int node = queue[front];
        double val = queueVal[front];
        front++;

        for (int i = 0; i < adjCount[node]; i++) {
            int nxt = adj[node][i];
            double w = weight[node][i];
            if (dist[nxt] < 0) {
                dist[nxt] = val * w;
                if (nxt == end) {
                    double result = dist[nxt];
                    free(dist);
                    free(queue);
                    free(queueVal);
                    return result;
                }
                queue[rear] = nxt;
                queueVal[rear] = dist[nxt];
                rear++;
            }
        }
    }

    free(dist);
    free(queue);
    free(queueVal);
    return -1.0;
}

double* calcEquation(char*** equations, int equationsSize, int* equationsColSize,
                     double* values, int valuesSize,
                     char*** queries, int queriesSize, int* queriesColSize,
                     int* returnSize) {

    HashMap* map = createMap(97);
    int id = 0;

    for (int i = 0; i < equationsSize; i++) {
        char* A = equations[i][0];
        char* B = equations[i][1];
        if (mapGet(map, A) == -1) mapPut(map, A, id++);
        if (mapGet(map, B) == -1) mapPut(map, B, id++);
    }

    int n = id;

    int* adjCount = (int*)calloc(n, sizeof(int));

    for (int i = 0; i < equationsSize; i++) {
        int u = mapGet(map, equations[i][0]);
        int v = mapGet(map, equations[i][1]);
        adjCount[u]++;
        adjCount[v]++;
    }

    int** adj = (int**)malloc(n * sizeof(int*));
    double** weight = (double**)malloc(n * sizeof(double*));

    for (int i = 0; i < n; i++) {
        adj[i] = (int*)malloc(adjCount[i] * sizeof(int));
        weight[i] = (double*)malloc(adjCount[i] * sizeof(double));
        adjCount[i] = 0;
    }

    for (int i = 0; i < equationsSize; i++) {
        int u = mapGet(map, equations[i][0]);
        int v = mapGet(map, equations[i][1]);
        double val = values[i];

        adj[u][adjCount[u]] = v;
        weight[u][adjCount[u]] = val;
        adjCount[u]++;

        adj[v][adjCount[v]] = u;
        weight[v][adjCount[v]] = 1.0 / val;
        adjCount[v]++;
    }

    double* result = (double*)malloc(queriesSize * sizeof(double));
    *returnSize = queriesSize;

    for (int i = 0; i < queriesSize; i++) {
        char* C = queries[i][0];
        char* D = queries[i][1];

        int s = mapGet(map, C);
        int e = mapGet(map, D);

        if (s == -1 || e == -1) {
            result[i] = -1.0;
            continue;
        }

        result[i] = bfs(s, e, n, adjCount, adj, weight);
    }

    return result;
}
```

