int** generateMatrix(int n, int* returnSize, int** returnColumnSizes) {
    int** mat = malloc(n * sizeof(int*));
    int* cols = malloc(n * sizeof(int));
    for (int i = 0; i < n; ++i) {
        mat[i] = calloc(n, sizeof(int));
        cols[i] = n;
    }

    int top = 0, bottom = n - 1, left = 0, right = n - 1;
    int num = 1, maxNum = n * n;
    while (num <= maxNum) {
        for (int j = left; j <= right && num <= maxNum; ++j) mat[top][j] = num++;
        ++top;
        for (int i = top; i <= bottom && num <= maxNum; ++i) mat[i][right] = num++;
        --right;
        for (int j = right; j >= left && num <= maxNum; --j) mat[bottom][j] = num++;
        --bottom;
        for (int i = bottom; i >= top && num <= maxNum; --i) mat[i][left] = num++;
        ++left;
    }

    *returnSize = n;
    *returnColumnSizes = cols;
    return mat;
}
