// Helper to create a justified line
char* makeLine(char** words, int l, int r, int wordsLen, int maxWidth, int isLast) {
    int wordsCount = r - l + 1;
    int chars = 0;
    for (int i = l; i <= r; ++i) chars += strlen(words[i]);

    char* line = malloc(maxWidth + 1);
    char* p = line;
    if (wordsCount == 1 || isLast) {
        // left-justified
        for (int i = l; i <= r; ++i) {
            int wlen = strlen(words[i]);
            memcpy(p, words[i], wlen); p += wlen;
            if (i < r) { *p++ = ' '; }
        }
        int rem = maxWidth - (p - line);
        while (rem-- > 0) *p++ = ' ';
    } else {
        int totalSpaces = maxWidth - chars;
        int spaceSlots = wordsCount - 1;
        int base = totalSpaces / spaceSlots;
        int extra = totalSpaces % spaceSlots;
        for (int i = l; i <= r; ++i) {
            int wlen = strlen(words[i]);
            memcpy(p, words[i], wlen); p += wlen;
            if (i < r) {
                int sp = base + (extra > 0 ? 1 : 0);
                extra--;
                for (int k = 0; k < sp; ++k) *p++ = ' ';
            }
        }
    }
    *p = '\0';
    return line;
}

char** fullJustify(char** words, int wordsSize, int maxWidth, int* returnSize, int** returnColumnSizes) {
    char** out = malloc((wordsSize + 5) * sizeof(char*));
    int* cols = malloc((wordsSize + 5) * sizeof(int));
    int outIdx = 0;

    int i = 0;
    while (i < wordsSize) {
        int j = i;
        int len = 0;
        while (j < wordsSize && len + strlen(words[j]) + (j - i) <= maxWidth) {
            len += strlen(words[j]);
            j++;
        }
        int l = i, r = j - 1;
        int isLast = (j == wordsSize);
        char* line = makeLine(words, l, r, len, maxWidth, isLast);
        out[outIdx] = line;
        cols[outIdx] = maxWidth;
        outIdx++;
        i = j;
    }

    *returnSize = outIdx;
    *returnColumnSizes = cols;
    return out;
}
