char* minWindow(char* s, char* t) {
    int need[128] = {0}, have[128] = {0};
    int required = 0;
    for (int i = 0; t[i]; ++i)
        if (need[(unsigned char)t[i]]++ == 0) required++;

    int formed = 0, left = 0, right = 0, start = 0, minLen = INT_MAX;

    for (; s[right]; ++right) {
        unsigned char c = s[right];
        have[c]++;
        if (have[c] == need[c]) formed++;

        while (formed == required) {
            if (right - left + 1 < minLen) {
                minLen = right - left + 1;
                start = left;
            }
            unsigned char lc = s[left++];
            if (have[lc]-- == need[lc]) formed--;
        }
    }

    if (minLen == INT_MAX) return strdup("");
    char* res = malloc(minLen + 1);
    strncpy(res, s + start, minLen);
    res[minLen] = '\0';
    return res;
