### ✅ **77. Combinations**
```c
#include <stdlib.h>

void backtrack(int n, int k, int start,
               int* path, int depth,
               int*** res, int* returnSize, int** colSize) {
    if (depth == k) {
        int* combo = malloc(k * sizeof(int));
        for (int i = 0; i < k; ++i) combo[i] = path[i];
        (*res)[*returnSize] = combo;
        (*colSize)[*returnSize] = k;
        (*returnSize)++;
        return;
    }

    for (int i = start; i <= n; ++i) {
        path[depth] = i;
        backtrack(n, k, i + 1, path, depth + 1, res, returnSize, colSize);
    }
}

int** combine(int n, int k, int* returnSize, int** returnColumnSizes) {
    int maxComb = 1;
    for (int i = 0; i < k; ++i)
        maxComb = maxComb * (n - i) / (i + 1);

    int** res = malloc(maxComb * sizeof(int*));
    int* colSize = malloc(maxComb * sizeof(int));
    int* path = malloc(k * sizeof(int));

    *returnSize = 0;
    backtrack(n, k, 1, path, 0, &res, returnSize, &colSize);

    *returnColumnSizes = colSize;
    free(path);
    return res;
}
```

